CustomField.formula:
IF(
    TEXT(CallType) = 'Inbound',
    IF(
        Contact_Center_Queue__c = '401K', 'Contact Center 401K',
        IF(
            Contact_Center_Queue__c = '1 Benefit Option', 'Contact Center Benefits',
            IF(
                Contact_Center_Queue__c = 'Web Support', 'Contact Center Web Support',
                IF(
                    Contact_Center_Queue__c = '5 Employment Verification', 'Contact Center Employment Verification',
                    IF(
                        Contact_Center_Queue__c = 'Section 125', 'Contact Center Section 125',
                        IF(
                            Contact_Center_Queue__c = '401K Core', 'Contact Center 401k Core',
                            IF(
                                Contact_Center_Queue__c = 'Escalations', 'Contact Center Escalations', ''
                            )
                        )
                    )
                )
            )
        )
    ),
    IF(
        OR(
            TEXT(CallType) = 'Transfer',
            TEXT(CallType) = 'Callback'
        ),
        IF(
            First_Assigned_Queue_for_Transfer__c = '401K', 'Contact Center 401K',
            IF(
                First_Assigned_Queue_for_Transfer__c = '1 Benefit Option', 'Contact Center Benefits',
                IF(
                    First_Assigned_Queue_for_Transfer__c = 'Web Support', 'Contact Center Web Support',
                    IF(
                        First_Assigned_Queue_for_Transfer__c = '5 Employment Verification', 'Contact Center Employment Verification',
                        IF(
                            First_Assigned_Queue_for_Transfer__c = 'Section 125', 'Contact Center Section 125',
                            IF(
                                First_Assigned_Queue_for_Transfer__c = '401K Core', 'Contact Center 401k Core',
                                IF(
                                    First_Assigned_Queue_for_Transfer__c = 'Escalations', 'Contact Center Escalations', ''
                                )
                            )
                        )
                    )
                )
            )
        ),''
    )
)
